typedef struct {
    uint32_t tls_vector[512];
    uint8_t thread_block[0x254];
    uint8_t thread_metadata[0x130];
    uint8_t tls_storage[0x94];
} BlackXboxThreadContext;
typedef struct {
    BlackXboxThreadContext *context;
    uint32_t start_context1;
    uint32_t start_context2;
    BlackGuestFunction start_routine;
} BlackXboxThreadLaunch;
typedef struct BlackXboxHostCriticalSection {
    uint32_t guest_address;
    CRITICAL_SECTION host_lock;
    struct BlackXboxHostCriticalSection *next;
} BlackXboxHostCriticalSection;
static SRWLOCK black_xbox_critical_sections_guard = SRWLOCK_INIT;
static BlackXboxHostCriticalSection *black_xbox_critical_sections;

static BlackXboxHostCriticalSection *black_xbox_critical_section(uint32_t guest_address, int create)
{
    BlackXboxHostCriticalSection *entry;
    if (!guest_address) return NULL;
    AcquireSRWLockExclusive(&black_xbox_critical_sections_guard);
    for (entry = black_xbox_critical_sections; entry; entry = entry->next) {
        if (entry->guest_address == guest_address) break;
    }
    if (!entry && create) {
        entry = (BlackXboxHostCriticalSection *)HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, sizeof(*entry));
        if (entry && !InitializeCriticalSectionAndSpinCount(&entry->host_lock, 0)) {
            HeapFree(GetProcessHeap(), 0, entry);
            entry = NULL;
        }
        if (entry) {
            entry->guest_address = guest_address;
            entry->next = black_xbox_critical_sections;
            black_xbox_critical_sections = entry;
        }
    }
    ReleaseSRWLockExclusive(&black_xbox_critical_sections_guard);
    return entry;
}

