static void trace_log(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    va_list copy;
    va_copy(copy, args);
    vprintf(format, args);
    if (trace_file) {
        vfprintf(trace_file, format, copy);
        fflush(trace_file);
    }
    va_end(copy);
    va_end(args);
}

