static int patch_a394a_short_conditionals(void)
{
    uint8_t *source = (uint8_t *)(uintptr_t)black_resolve_guest_function(0x000A394Au);
    uint8_t *target_a39fa = (uint8_t *)(uintptr_t)black_resolve_guest_function(0x000A39FAu);
    uint8_t *target_a3a31 = (uint8_t *)(uintptr_t)black_resolve_guest_function(0x000A3A31u);
    uint8_t *site_a3987, *site_a39d5, *site_a39dd, *island_a39fa, *island_a3a31;
    uint8_t *padding;
    uint8_t island[10];
    int32_t displacement;
    DWORD old_protection;
    size_t i;
    if (!source || !target_a39fa || !target_a3a31) return 0;
    site_a3987 = source + 0x3D;
    site_a39d5 = source + 0x8B;
    site_a39dd = source + 0x93;
    padding = source + 0xA2;
    island_a3a31 = padding;
    island_a39fa = padding + 5;
    if (memcmp(site_a3987, "\x75\x71", 2) != 0 || memcmp(site_a39d5, "\x75\x5A", 2) != 0 ||
        memcmp(site_a39dd, "\x74\x52", 2) != 0 || memcmp(padding, "\xCC\xCC\xCC\xCC\xCC\xCC\xCC\xCC\xCC\xCC", 10) != 0) {
        trace_log("event=a394a_short_jcc_failed reason=unexpected_bytes source=0x%08X padding=0x%08X\n",
            (uint32_t)(uintptr_t)source, (uint32_t)(uintptr_t)padding);
        return 0;
    }
    island[0] = 0xE9;
    displacement = (int32_t)((uint32_t)(uintptr_t)target_a3a31 - (uint32_t)(uintptr_t)(island_a3a31 + 5));
    memcpy(island + 1, &displacement, 4);
    island[5] = 0xE9;
    displacement = (int32_t)((uint32_t)(uintptr_t)target_a39fa - (uint32_t)(uintptr_t)(island_a39fa + 5));
    memcpy(island + 6, &displacement, 4);
    if (!VirtualProtect(padding, sizeof(island), PAGE_EXECUTE_READWRITE, &old_protection)) return 0;
    memcpy(padding, island, sizeof(island));
    FlushInstructionCache(GetCurrentProcess(), padding, sizeof(island));
    VirtualProtect(padding, sizeof(island), old_protection, &old_protection);
    for (i = 0; i < 3; ++i) {
        uint8_t *site = i == 0 ? site_a3987 : (i == 1 ? site_a39d5 : site_a39dd);
        uint8_t *island_target = i == 0 ? island_a39fa : island_a3a31;
        uint32_t distance = (uint32_t)(uintptr_t)island_target - (uint32_t)(uintptr_t)(site + 2);
        int8_t rel8 = (int8_t)distance;
        if (distance > 127u || !VirtualProtect(site + 1, 1, PAGE_EXECUTE_READWRITE, &old_protection)) return 0;
        site[1] = (uint8_t)rel8;
        FlushInstructionCache(GetCurrentProcess(), site + 1, 1);
        VirtualProtect(site + 1, 1, old_protection, &old_protection);
    }
    trace_log("event=a394a_short_jcc_rebased site_a3987=0x%08X target_a39fa=0x%08X site_a39d5=0x%08X site_a39dd=0x%08X target_a3a31=0x%08X islands=0x%08X,0x%08X\n",
        (uint32_t)(uintptr_t)site_a3987, (uint32_t)(uintptr_t)target_a39fa,
        (uint32_t)(uintptr_t)site_a39d5, (uint32_t)(uintptr_t)site_a39dd,
        (uint32_t)(uintptr_t)target_a3a31, (uint32_t)(uintptr_t)island_a3a31,
        (uint32_t)(uintptr_t)island_a39fa);
    return 1;
}

